  function openEntry(raffle=activeRaffle){if(!user){setModal('auth');return}setEntryError('');setEntryForm({name:profile?.name||user.displayName||'',email:profile?.email||user.email||'',phone:profile?.phone||'',contact:profile?.contact||'',address:profile?.address||'',payoutMethod:profile?.payoutMethod||'',payoutName:profile?.payoutName||'',payoutAccount:profile?.payoutAccount||'',payoutPhone:profile?.payoutPhone||'',paymentMethod:'',paymentAccount:'',couponCode:'',ticketCount:'1',raffleId:raffle?.id||availableRaffles[0]?.id||''});setModal('entry')}
  async function addEntry(e) {
    e.preventDefault()
    if(!user){setModal('auth');return}
    if(profile?.status==='suspended'||profile?.status==='deleted'){notify('ဤအကောင့်ဖြင့် ကံစမ်းခွင့်တောင်း၍မရပါ။');return}
    if(!profile?.approved){notify('အကောင့်ဖွင့်ခြင်းသည် တစ်ကြိမ်သာလုပ်ရန်ဖြစ်ပြီး Admin အတည်ပြုပြီးမှ ကံစမ်းမဲဝင်နိုင်ပါသည်။');return}
    try {
      setEntryError('')
      const raffleId=entryForm.raffleId,ticketCount=Math.floor(Number(entryForm.ticketCount))
      if(!raffleId)throw Error('ကံစမ်းမဲအစီအစဉ်ကို ရွေးပါ။')
      const selected=raffles.find(r=>r.id===raffleId)
      if(!selected)throw Error('မဲအစီအစဉ် မတွေ့ပါ။')
      const now=Date.now(),mode=selected.entryMode||'free',unitPoints=Math.max(1,Number(selected.pointsPerChance||1)),pointsCost=mode==='points'?unitPoints*ticketCount:0
      if(!['active','scheduled'].includes(selected.status)||now<Date.parse(selected.openAt||0)||selected.drawAt&&now>=Date.parse(selected.drawAt))throw Error('ဤကံစမ်းမဲကို ဝင်ရောက်နိုင်သည့်အချိန် မဟုတ်ပါ။')
      if(ticketCount<1||ticketCount>100)throw Error('ကံစမ်းခွင့်အရေအတွက်ကို 1 မှ 100 အတွင်းထည့်ပါ။')
      const remainingTickets=Math.max(0,Number(selected.maxTickets||0)-Number(selected.reservedTicketCount??selected.ticketCount??0)),perUser=Math.max(1,Number(selected.maxTicketsPerUser??(mode==='paid'?selected.maxTickets:1)))
      if(ticketCount>remainingTickets)throw Error(remainingTickets===0?'ဤမဲ၏ ကံစမ်းခွင့်အားလုံး ပြည့်သွားပါပြီ။ Admin ကို Website မှ မဲအစီအစဉ်ပြင်ဆင်ရန်နှင့် ကံစမ်းခွင့်အများဆုံးကို တိုးပေးရန် ဆက်သွယ်ပါ။':`ဤမဲတွင် ကံစမ်းခွင့် ${remainingTickets} စောင်သာ ကျန်ပါသည်။ တောင်းဆိုသည့်အရေအတွက်ကို လျှော့ပါ သို့မဟုတ် Admin ကို အများဆုံးအရေအတွက်တိုးရန် ဆက်သွယ်ပါ။`)
      if(ticketCount>perUser)throw Error(`လူတစ်ဦးလျှင် အများဆုံး ${perUser} မဲသာ တောင်းဆိုနိုင်ပါသည်။`)
      if(mode==='paid'&&(!entryForm.paymentMethod||!entryForm.paymentAccount))throw Error('ငွေပေးချေမှုနည်းလမ်းနှင့် လွှဲပြောင်းသူ/အကောင့်အချက်အလက် ဖြည့်ပါ။')
      if(mode==='points'&&Number(profile?.pointsBalance||0)<pointsCost&&!safe(entryForm.couponCode))throw Error(`လိုအပ်သော ပွိုင့် ${money(pointsCost)} ရှိရပါမည်။ လက်ကျန် ${money(profile?.pointsBalance||0)} ပွိုင့်ဖြစ်သည်။`)
      if(!navigator.onLine)throw Error('အင်တာနက်ချိတ်ဆက်မှု မရှိပါ။ အင်တာနက်ပြန်ရမှ ထပ်မံပေးပို့ပါ။')
      setLoading(true)
      const entryRef=doc(db,'participants',`${user.uid}_${raffleId}`),raffleRef=doc(db,'raffles',raffleId)
      const transaction=runTransaction(db,async tx=>{
        const [previous,raffleSnap]=await Promise.all([tx.get(entryRef),tx.get(raffleRef)])
        if(previous.exists())throw Error('ဤမဲအစီအစဉ်အတွက် သင်ကံစမ်းခွင့်တောင်းဆိုထားပြီးပါပြီ။')
        if(!raffleSnap.exists())throw Error('မဲအစီအစဉ် မတွေ့ပါ။')
        const current=raffleSnap.data(),reserved=Number(current.reservedTicketCount??current.ticketCount??0),capacity=Number(current.maxTickets||0),userLimit=Number(current.maxTicketsPerUser??((current.entryMode||'free')==='paid'?capacity:1))
        if(reserved+ticketCount>capacity)throw Error(`လက်ကျန်မဲ ${Math.max(0,capacity-reserved)} စောင်သာရှိပါသည်။`)
        if(ticketCount>userLimit)throw Error(`လူတစ်ဦးလျှင် အများဆုံး ${userLimit} မဲသာ တောင်းဆိုနိုင်ပါသည်။`)
        if(!['active','scheduled'].includes(current.status)||Date.now()<Date.parse(current.openAt||0)||current.drawAt&&Date.now()>=Date.parse(current.drawAt))throw Error('မဲစာရင်းဖွင့်ချိန် သို့မဟုတ် ပိတ်ချိန်ကို ကျော်သွားပါပြီ။')
        tx.update(raffleRef,{reservedTicketCount:reserved+ticketCount})
        tx.set(entryRef,{name:safe(entryForm.name)||profile?.name||user.displayName||'',email:safe(entryForm.email)||profile?.email||user.email||'',phone:safe(entryForm.phone)||profile?.phone||'',contact:safe(entryForm.contact)||profile?.contact||'',address:safe(entryForm.address),payoutMethod:safe(entryForm.payoutMethod),payoutName:safe(entryForm.payoutName),payoutAccount:safe(entryForm.payoutAccount),payoutPhone:safe(entryForm.payoutPhone),paymentMethod:mode==='paid'?safe(entryForm.paymentMethod):'',paymentAccount:mode==='paid'?safe(entryForm.paymentAccount):'',couponCode:mode==='points'?safe(entryForm.couponCode):'',ticketCount,spinsUsed:0,raffleId,status:'pending',entryMode:mode,pointsCost,unitPrice:mode==='paid'?Number(selected.ticketPrice||0):0,userId:user.uid,avatarUrl:profile?.avatarUrl||'',createdAt:serverTimestamp()})
      })
      let timeoutId
      try { await Promise.race([transaction,new Promise((_,reject)=>{timeoutId=setTimeout(()=>reject(new Error('တောင်းဆိုမှုကို အချိန်မီအတည်မပြုနိုင်သေးပါ။ မဲနှိုက်သူစာရင်းကို အရင်စစ်ပြီးမှ ထပ်မံပေးပို့ပါ။')),20000)})]) }
      finally {clearTimeout(timeoutId)}
      setModal('');notify(mode==='free'?'ကံစမ်းခွင့်တောင်းဆိုမှု ပေးပို့ပြီးပါပြီ။':'ကံစမ်းခွင့်တောင်းဆိုမှု ပေးပို့ပြီးပါပြီ။ Admin မှ ငွေလွှဲ သို့မဟုတ် ပွိုင့်အချက်အလက်ကို စစ်ဆေးအတည်ပြုမည်။')
    }catch(err){
      let message=err.message||'ကံစမ်းခွင့် ပေးပို့မရပါ။'
      if(err.code==='permission-denied')message='Firestore ခွင့်ပြုချက်မရပါ။ အကောင့်အတည်ပြုမှု၊ မဲဖွင့်ချိန်နှင့် အများဆုံးမဲအရေအတွက်ကို Admin ထံ စစ်ဆေးခိုင်းပါ။'
      else if(err.code==='unavailable'||err.code==='deadline-exceeded')message='Firebase ချိတ်ဆက်မှုနှေးနေပါသည်။ မဲနှိုက်သူစာရင်းကို အရင်စစ်ပြီးမှ ထပ်မံပေးပို့ပါ။'
      setEntryError(message);notify(message)
    }finally{setLoading(false)}
  }
  async function addDonation(e) { e.preventDefault(); if(!user){setModal('auth');return}; if(!profile?.approved){notify('အလှူစာရင်းတင်ရန် Admin အတည်ပြုချက်လိုအပ်ပါသည်။');return}; try {setLoading(true);const quantity=Number(donForm.quantity||1),unitValue=Number(donForm.unitValue||0),amount=donForm.kind==='cash'?Number(donForm.value||0):quantity*unitValue;await addDoc(collection(db,'donations'),{...donForm,name:safe(donForm.name),item:safe(donForm.item),kind:donForm.kind,quantity,unitValue,value:amount,contact:safe(donForm.contact),note:safe(donForm.note),status:'pending',userId:user.uid,createdAt:serverTimestamp()});setModal('');notify('အလှူစာရင်းကို ပေးပို့ပြီးပါပြီ။')}catch(err){notify(err.message)}finally{setLoading(false)} }
