  async function changeAccountStatus(account,status){if(!isAdmin||account.uid===user.uid)return;if(status==='deleted'&&!window.confirm(`${account.name||account.email||'ဤအကောင့်'} ကို ပယ်ဖျက်ပြီး ကိုယ်ရေးအချက်အလက်ကို ဖျက်သိမ်းမလား။ ယခင်မဲနှင့် ဆုမှတ်တမ်းများကို စာရင်းစစ်ရန် ချန်ထားမည်။`))return;try{const ref=doc(db,'users',account.uid),updates=status==='deleted'?{status:'deleted',approved:false,name:'ပယ်ဖျက်ထားသောအကောင့်',email:'',phone:'',contact:'',telegram:'',address:'',avatarUrl:'',pointsBalance:0,deletedAt:serverTimestamp(),deletedBy:user.uid}:{status,statusChangedAt:serverTimestamp(),statusChangedBy:user.uid};if(['deleted','suspended'].includes(status)&&account.role==='admin')await deleteDoc(doc(db,'admins',account.uid));await updateDoc(ref,updates);notify(status==='deleted'?'အကောင့်ကို ပယ်ဖျက်မှတ်သားပြီး ကိုယ်ရေးအချက်အလက်များ ဖယ်ရှားလိုက်ပါပြီ။':'အကောင့်အခြေအနေ ပြောင်းလဲပြီးပါပြီ။')}catch(e){notify(e.message)}}
