      const slots=wheelSlots.length?wheelSlots:await getPrizeSlots(raffle)
      if(raffle.entryMode==='paid'){const received=Number(raffle.ticketCount||0)*Number(raffle.ticketPrice||0),cashAwards=slots.reduce((sum,slot)=>sum+(slot.valueType==='cash'?Number(slot.value||0):0),0);if(cashAwards>0&&received<=cashAwards)throw Error(`အတည်ပြုပြီးရောင်းချသောမဲမှ ဝင်ငွေ ${money(received)} ကျပ်သည် ဆုငွေ ${money(cashAwards)} ကျပ်ထက် မများသေးပါ။ အရောင်းပြည့်အောင် စောင့်ပါ၊ ဆုကြေးလျှော့ပါ သို့မဟုတ် Admin ထံ အချိန်တိုးရန်တောင်းပါ။`)}
