          if(!['active','scheduled'].includes(r.status)||now<Date.parse(r.openAt||0)||r.drawAt&&now<Date.parse(r.drawAt))throw Error('မဲဖောက်မည့်အချိန် မရောက်သေးပါ။ မဲကတ်ရှိ Countdown ကိုကြည့်ပါ။')
