          const claimRefs=slots.map(s=>doc(db,'raffles',raffle.id,'claimedSlots',s.id)),claims=await Promise.all(claimRefs.map(ref=>tx.get(ref))),available=slots.filter((_,i)=>!claims[i].exists())
          const spinsLeft=Math.max(1,Number(r.ticketCount||0)-Number(r.drawSpinsUsed||0)),willMiss=available.length<spinsLeft,wheelSlices=available.map(slot=>({id:slot.id,name:slot.name,item:slot.item,value:Number(slot.value||0),valueType:slot.valueType||'goods',imageUrl:slot.imageUrl||'',weight:1}));if(willMiss)wheelSlices.push({id:`miss-${spinId}`,name:'မပေါက်',item:'ဤအလှည့်တွင် ဆုမရပါ',weight:spinsLeft-available.length})
          const wheelIndex=available.length>=spinsLeft?randomInt(available.length):randomInt(spinsLeft),won=available.length>0&&wheelIndex<available.length,slot=won?available[wheelIndex]:null,winnerId=won?crypto.randomUUID():''
          tx.update(entryRef,{spinsUsed:Number(e.spinsUsed||0)+1});tx.update(raffleRef,{drawSpinsUsed:Number(r.drawSpinsUsed||0)+1,drawLocked:true,lastSpinEntryId:entry.id})
