          return{won,raffleTitle:r.title,entryId:entry.id,winnerName:e.name,prizeName:slot?.name||'မပေါက်ပါ',prizeItem:slot?.item||'ဤအလှည့်တွင် ဆုမရပါ',prizeValue:slot?.value||0,prizeImage:slot?.imageUrl||'',slotId:slot?.id||'',wheelSlices,wheelIndex:won?wheelIndex:(available.length>=spinsLeft?0:wheelSlices.length-1)}
